@startuml

class Center {
  + name : string
  + address : string
}

class Room {
  + number : int
  + capacity : int
}

class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

class Trainer {
  + diploma : string
}

class Prospect {}

class Intern {}

abstract class Participant {}

class IndividualSession {
  + startDate : date
  + startHour : time
}

class GroupSession {
  + startDate : date
  + startHour : time
  + sessionType : string
}

Center "1" *-- "*" Room
Room "1" -- "*" Participant
Person "1" *-- "*" Participant
Trainer "0..*" -- "*" GroupSession
Prospect "0..*" -- "*" Participant
Intern "0..*" -- "*" Trainer
IndividualSession "0..*" -- "*" Participant
GroupSession "0..*" -- "*" Participant

@enduml

